#!/usr/bin/env node
// Generated by Keel — standing-gates Stop hook. Copy to .claude/hooks/keel-gates.mjs.
// Replaces the hand-ticked "size + link check" Pre-PR box: when Claude is about to stop, runs
// `node .keel/doc-size.mjs` and, on a LINK ERROR (exit 1), blocks the stop once with the
// checker's output so the agent fixes it. Budget verdicts (archive/split/manual) are left to
// doc-sync and never block. Silent when the check passes or the checker is absent.
// Blocks at most once per stop (stop_hook_active), so it can never loop.
// Self-test (needs keel-doc-size.mjs beside this file, as in the keel repo):
//   node keel-gates-hook.mjs --self-test
import { readFileSync, existsSync, mkdtempSync, mkdirSync, writeFileSync, copyFileSync } from 'fs'
import { spawnSync } from 'child_process'
import { tmpdir } from 'os'
import { join, dirname } from 'path'

if (process.argv[2] === '--self-test') {
  const cwd = mkdtempSync(join(tmpdir(), 'keel-gates-'))
  const run = stdin => spawnSync(process.execPath, [process.argv[1]], { cwd, encoding: 'utf8', input: stdin }).stdout
  const ok = (c, m) => { if (!c) { console.log('FAIL ' + m); process.exit(1) } }
  ok(run('{}') === '', 'silent without .keel/doc-size.mjs')
  mkdirSync(join(cwd, '.keel')); mkdirSync(join(cwd, 'docs/design'), { recursive: true })
  copyFileSync(join(dirname(process.argv[1]), 'keel-doc-size.mjs'), join(cwd, '.keel/doc-size.mjs'))
  writeFileSync(join(cwd, 'docs/DESIGN.md'), '# Design\n\n## Parts\n\n| Part | Sections |\n|---|---|\n')
  writeFileSync(join(cwd, 'docs/design/01-tokens.md'), '# Design — tokens\n\nbody\n')
  const out = run('{"stop_hook_active":false}')
  ok(/"decision":"block"/.test(out) && /LINK ERROR/.test(out), 'blocks on a split-link error: ' + out)
  ok(run('{"stop_hook_active":true}') === '', 'never blocks twice in one stop')
  writeFileSync(join(cwd, 'docs/DESIGN.md'), '# Design\n\n## Parts\n\n| Part | Sections |\n|---|---|\n| [01](design/01-tokens.md) | tokens |\n')
  writeFileSync(join(cwd, 'docs/design/01-tokens.md'), '# Design — tokens\n> Part of [DESIGN.md](../DESIGN.md) · all parts listed there.\n\nbody\n')
  ok(run('{}') === '', 'silent once the links are fixed')
  console.log('ok'); process.exit(0)
}

let input = {}
try { input = JSON.parse(readFileSync('/dev/stdin', 'utf8')) } catch {}
if (input.stop_hook_active || !existsSync('.keel/doc-size.mjs')) process.exit(0)

const r = spawnSync(process.execPath, ['.keel/doc-size.mjs'], { encoding: 'utf8', timeout: 20000 })
if (r.status !== 1) process.exit(0)

const errors = (r.stdout + r.stderr).split('\n').filter(l => /LINK ERROR/i.test(l)).slice(0, 10)
process.stdout.write(JSON.stringify({
  decision: 'block',
  reason: 'keel gate: node .keel/doc-size.mjs found split-doc link errors. Fix each link (add the ' +
    'Parts row or the "> Part of" line; never delete a part), re-run the check, then finish.\n' +
    (errors.join('\n') || (r.stdout + r.stderr).slice(-1500)),
}))
process.exit(0)
